  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_ARCH.valueNotes.0": "single は短い推論連鎖を持つ単純なシナリオに適しています。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_ARCH.valueNotes.1": "multi 技術分析、インテル、リスク、その他の専門サブエージェント間の協力を支援します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_CRITIC_ENABLED.impact.0": "Critic の LLM 呼び出しを 1 回追加し、retry 判定時のみ最大 1 回のステージ再実行を追加します。",
