  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_CRITIC_ENABLED.summary": "Native Multi の Decision ステージ前に、読み取り専用の証拠レビューを 1 回実行します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_CRITIC_ENABLED.title": "有界 Multi-Agent Critic",
