  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_FEATURES_ACKNOWLEDGED_OFF.valueNotes.0": "既定はオフです。API モデルが使えるか Agent オフを確認するまで、Agent モデルの準備チェックは要対応のままです。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_FEATURES_ACKNOWLEDGED_OFF.valueNotes.1": "ツール対応 API モデルが Agent で利用可能になると、この確認は自動的に上書きされ、Agent 準備を妨げません。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_FEATURES_ACKNOWLEDGED_OFF.valueNotes.2": "CLI バックエンドは生成専用のままです。このスイッチで CLI が Agent 対応になることはありません。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_GENERATION_BACKEND.impact.0": "アシスタントの応答経路とツールのエントリーポイントに影響を与えます。アシスタントが使えるツールは変わりません。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_GENERATION_BACKEND.notes.0": "デフォルトの動作を復元するには、自動を選択して保存してください。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_GENERATION_BACKEND.notes.1": "この設定はStock Inquiry Assistantにのみ影響し、通常の個別株分析や市場レビューの生成には影響しません。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_GENERATION_BACKEND.summary": "Stock Askアシスタントで回答を生成する方法を決め、市場見積もり、ニュース、過去のデータなどを照会するためのツールと連携しましょう。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_GENERATION_BACKEND.title": "株式照会の生成方法",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_GENERATION_BACKEND.usage": "通常は「自動」のままです。 システムは現在利用可能な方法を選択して質問に答え、データツールを呼び出します。 明確な固定方法がなければ、調整は不要です。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_GENERATION_BACKEND.valueNotes.0": "迷っているならオートを選びましょう。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_GENERATION_BACKEND.valueNotes.1": "アシスタントを通常のモデル設定にピン留めしたい場合のみ「デフォルトモデル設定」を選択してください。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_GENERATION_BACKEND.valueNotes.2": "ローカル CLI バックエンドは現在、銘柄相談アシスタントのデータツール呼び出しを直接実行できません。明示的に手動設定した場合、この機能は利用不可と報告されます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_INVESTMENT_COMMITTEE_MODE.impact.0": "エージェント編成の深さとレポートの委員会セクションに影響します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_INVESTMENT_COMMITTEE_MODE.notes.0": "エージェント multi モード能力が必要です。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_INVESTMENT_COMMITTEE_MODE.summary": "複数ロールの投資委員会形式で分析し、構造化された異論を提示します。",
