  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_INVESTMENT_COMMITTEE_MODE.valueNotes.0": "オフにすると既存の単一パス分析動作を維持します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_MAX_STEPS.impact.0": "推論の深さ、持続時間、トークン消費に影響を与えます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_MAX_STEPS.notes.0": "非常に低い値は不完全な推論を引き起こす可能性があります。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_MAX_STEPS.summary": "エージェントの最大推論ステップの制限を制御します。",
