  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_MAX_STEPS.valueNotes.0": "より高いステップはより深い推論を可能にしますが、時間とトークンコストを増加させます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_MAX_STEPS.valueNotes.1": "複雑なシナリオ(例:マルチストラテジーのオーケストレーション)では、より高い値が必要になることがあります。",
