  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_MODE.impact.0": "これは銘柄分析プロセス、レポート作成の品質、そして LLM 呼び出し回数。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_MODE.notes.0": "エージェントモードはより多くのトークンと時間を消費します。深い推論を必要とするシナリオに最適です。",
