  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_MULTI_STRATEGY_DELIBERATION.summary": "複数戦略の専門エージェントを並行スケジュールし、最終的な見解差の説明を出します。",
