  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_MULTI_STRATEGY_DELIBERATION.valueNotes.0": "オフは従来の合成動作をバイト単位で維持します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_MULTI_STRATEGY_DELIBERATION.valueNotes.1": "オンにするとマルチ戦略合議と最終的な見解差の説明が有効になります。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_NL_ROUTING.impact.0": "ボットとのインタラクション経験とエージェントトリガー方法に影響を与えます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_NL_ROUTING.notes.0": "エージェントモードと対応するボットチャンネルの両方を有効にする必要があります。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_NL_ROUTING.summary": "ボットディスパッチャーが自然言語認識を用いてストッククエリをエージェントにルーティングできるようにします。",
