  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_NL_ROUTING.valueNotes.0": "ボット統合にのみ影響します(Feishu, Telegram, ウェブではなく、 API.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_ORCHESTRATOR_MODE.impact.0": "マルチエージェント分析の深さとリソース消費に影響を与えます。",
