  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_ORCHESTRATOR_MODE.valueNotes.0": "より完全なモードはより深い分析を可能にしますが、より多くの時間とトークンを消費します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_ORCHESTRATOR_MODE.valueNotes.1": "specialist モードでは、各戦略専用のエージェントが起動します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_ORCHESTRATOR_TIMEOUT_S.impact.0": "エージェント分析の最大待ち時間に影響を与えます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_ORCHESTRATOR_TIMEOUT_S.notes.0": "タイムアウトは他の銘柄の分析プロセスに影響を与えません。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_ORCHESTRATOR_TIMEOUT_S.summary": "エージェント実行のためのタイムアウト予算を数秒で共有。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.agent.AGENT_ORCHESTRATOR_TIMEOUT_S.title": "エージェント・タイムアウト",
