  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.anspire_llm.valueNotes.0": "このパスは主に、LLM_CHANNELS または LITELLM_MODEL を使わない簡易設定向けです。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.anspire_llm.valueNotes.1": "LITELLM_CONFIG、LLM_CHANNELS、または明示的な LITELLM_MODEL が設定されている場合、実行時は既存の優先順位に従って選択します。",
