  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.GENERATION_BACKEND_MAX_OUTPUT_BYTES.valueNotes.0": "ログは脱感度化された断片のみを示し、分析内容、環境変数、キー、ローカルパスは表示されません。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.GENERATION_BACKEND_TIMEOUT_SECONDS.summary": "1世代の待機時間を制限します。",
