  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.GENERATION_BACKEND_TIMEOUT_SECONDS.valueNotes.0": "タイムアウトは生成を停止し、明確なタイムアウトエラーを記録します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.GENERATION_BACKEND.impact.0": "一般的な分析、市場レビュー、テキスト生成のエントリーポイントに影響を与えますが、Stock Ask Assistantのツール実行ルールは変更しません。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.GENERATION_BACKEND.notes.0": "既定の動作に戻すには、「既定のモデル設定」を選択して保存してください。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.GENERATION_BACKEND.notes.1": "ローカル CLI バックエンドはまだ実験段階です。出力が不安定だったり故障が頻発する場合は、デフォルトモデル設定に戻してください。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.GENERATION_BACKEND.notes.2": "デフォルトのモデル設定では、既存の API キー、モデル接続、フォールバックモデル設定が引き続き使用されます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.GENERATION_BACKEND.summary": "システムが個別株分析、市場レビュー、通常のテキスト回答を生成する方法を決めましょう。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.GENERATION_BACKEND.title": "解析生成法",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.GENERATION_BACKEND.usage": "通常はデフォルトモデル設定のままにします。地元のものを選んでください CLI 対応するバックエンドのみ CLI このマシンにインストールされログインされており、分析コンテンツの処理を信頼しています。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.GENERATION_BACKEND.valueNotes.0": "ローカル CLI 生成方法はオフラインモデルではなく、ローカルで起動されるコマンドラインプログラムです。 裏方のサービスは、ティッカーコード、ニュース、ポートフォリオコンテキスト、分析依頼、レポートドラフトを扱うことがあります。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.GENERATION_BACKEND.valueNotes.1": "Docker、クラウドサーバー、CI には、ローカルのログイン状態が自動的には引き継がれません。StockPulse は Codex、Claude、OpenCode の認証情報ファイルを読み取りませんが、対応する CLI は自身のログイン状態を使用する場合があります。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.GENERATION_FALLBACK_BACKEND.impact.0": "局所的影響 CLI 株式分析、市場レビュー、フリーフォームテキスト生成のための失敗処理。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.GENERATION_FALLBACK_BACKEND.notes.0": "ホープ・ローカル CLI エラーが故障直後に露出した場合は「無効化」を選択してください。 「デフォルトモデル構成」を選択してクラウドモデルを引き続き試したいと思っています。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.GENERATION_FALLBACK_BACKEND.summary": "失敗したローカルかどうかを選択します。 CLI 生成はエラーで止まるか、次にデフォルトモデル設定を試してみるべきです。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.GENERATION_FALLBACK_BACKEND.title": "フォールバック生成方法",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.GENERATION_FALLBACK_BACKEND.usage": "「無効」を選択すると失敗するとエラーが発生します。 「デフォルトモデル構成」を選択すると、すでに設定している標準モデルを試すことを意味します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.GENERATION_FALLBACK_BACKEND.valueNotes.0": "モデル間のフォールバックにはフォールバックモデルを用いましょう。このフィールドはローカルのみを扱います CLI バックエンドとデフォルトモデル設定の比較。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.GENERATION_FALLBACK_BACKEND.valueNotes.1": "主要な生成方法がすでにデフォルトモデル設定の場合、このフィールドは追加の影響を持ちません。",
