  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.provider_keys.usage": "プロバイダーコンソールでキーを作成します。関連するマルチキーバリアントでは、回転や負荷分散のために英語のコンマが使われます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.provider_keys.valueNotes.0": "秘密フィールドはウェブ設定ページでマスクされています。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.provider_keys.valueNotes.1": "チャネルモードは読み取られます LLM_<NAME>_API_KEY(S) まず。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.VISION_MODEL.impact.0": "視力分析のみに影響します。レポートやエージェントのプライマリモデルは変更されません。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.VISION_MODEL.summary": "画像理解タスクに使用されるモデルを選択します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.ai_model.VISION_MODEL.title": "ビジョンモデル",
