  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.BACKTEST_ENABLED.impact.0": "戦略の重みキャリブレーション、メモリキャリブレーション、バックテストレポート生成に影響を与えます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.BACKTEST_ENABLED.notes.0": "エージェント戦略の自動重み付け機能はバックテストデータに依存しています。",
