  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.BACKTEST_ENABLED.valueNotes.0": "バックテストデータは戦略の自動重み付けに入力されます(AGENT_SKILL_AUTOWEIGHT)およびメモリキャリブレーション。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.BACKTEST_ENABLED.valueNotes.1": "バックテストのクローズは既存のバックテスト記録には影響しませんが、新しいバックテストの評価は停止します。",
