  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.BACKTEST_ENGINE_VERSION.usage": "通常は変える必要はありません。ラベルは現在の評価ロジックバージョンを示します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.BACKTEST_ENGINE_VERSION.valueNotes.0": "バージョンによって評価アルゴリズムや判断ルールが異なる場合があります。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.eval_params.impact.0": "バックテストの判断基準、カバレッジ、戦略の重み計算に影響を与えます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.eval_params.notes.0": "これら3つのパラメータは同時にバックテスト結果に影響を与えます。それらを一緒に調整する。",
