  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.backtest.eval_params.valueNotes.2": "リターン BACKTEST_NEUTRAL_BAND_PCT 中立的なラベルを貼り、正しいか間違っているかを判断しません。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.base.STOCK_LIST.impact.0": "分析範囲、通知内容、保存履歴レポートに影響を与えます。",
