  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.base.STOCK_LIST.valueNotes.0": "タイムドモードがトリガーされるたびに、現在保存されたデータが再読み込まれます STOCK_LIST。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.base.STOCK_LIST.valueNotes.1": "コマンドラインが一時的に渡された場合 --stocks、この手動操作のみが影響を受けます。今後予定された作業はロックされません。",
