  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.data_source.ALPHASIFT_INSTALL_SPEC.valueNotes.0": "カスタムローカルパスやホイールは修復エンドポイントによって処理されません。まずはバックエンドのPython環境にインストールしてください。",
