  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_RECEIVE_ID_TYPE.usage": "選べ chat_id グループの場合、選んでください open_id 特定のユーザーにP2Pメッセージを送信するためのものでした。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_RECEIVE_ID_TYPE.valueNotes.0": "効果は FEISHU_CHAT_ID また、 も設定されています。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_RECEIVE_ID_TYPE.valueNotes.1": "型が実際のIDと一致しない場合、送信は無効な receive_id エラー。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_STREAM_ENABLED.impact.0": "影響 Feishu アプリケーションボットとのやり取り、またはストリームボットパス。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_STREAM_ENABLED.impact.1": "変わらない FEISHU_WEBHOOK_URL グループWebhookの配信セマンティクス。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_STREAM_ENABLED.notes.0": "保存後に該当するボット/サービスプロセスを再起動してください。既存の長距離接続は自動的に再構築されるわけではありません。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_STREAM_ENABLED.notes.1": "故障は Feishu アプリのボットパスであって、メインの分析フローではありません。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_STREAM_ENABLED.summary": "有効化 Feishu アプリケーションボット/ストリームボットの長時間接続モード。それは Feishu グループWebhookスイッチ。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_STREAM_ENABLED.title": "Feishu ストリームモード",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_STREAM_ENABLED.usage": "有効化するのは Feishu アプリは作成、公開、権限付与、イベント設定を行います。 FEISHU_APP_ID および FEISHU_APP_SECRET また、必須条件です。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_STREAM_ENABLED.valueNotes.0": "true 実行時間を許容します Feishu アプリのボット配信モード。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_STREAM_ENABLED.valueNotes.1": "false ストリームモードを無効にします。グループメッセージ配信は依然として FEISHU_WEBHOOK_URL.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_STREAM_ENABLED.valueNotes.2": "アプリの認証情報やこのスイッチだけではグループWebhookの配信は有効になりません。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_WEBHOOK_URL.impact.0": "影響は Feishu 通知チャンネル;デリバリーの失敗は、主要な分析フローを妨げるべきではありません。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_WEBHOOK_URL.notes.0": "使用しないでください FEISHU_APP_SECRET として FEISHU_WEBHOOK_SECRET.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_WEBHOOK_URL.notes.1": "IP許可リストが有効の場合 Feishu, 、ランタイム環境のアウトバウンドIPを追加します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_WEBHOOK_URL.summary": "分析レポートを送信します Feishu カスタムボットのウェブフックを通じてグループ化します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_WEBHOOK_URL.title": "Feishu ウェブフックURL",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_WEBHOOK_URL.usage": "ターゲット内でカスタムボットを作成します Feishu open-apis/bot/v2/hookのwebhookURLをここにまとめて貼り付けてください。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_WEBHOOK_URL.valueNotes.0": "署名が有効なら、こちらも設定します FEISHU_WEBHOOK_SECRET.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_WEBHOOK_URL.valueNotes.1": "キーワード保護が有効であれば、 FEISHU_WEBHOOK_KEYWORD;送信者は自動的にその前に置きます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.FEISHU_WEBHOOK_URL.valueNotes.2": "FEISHU_APP_ID / FEISHU_APP_SECRET アプリ、クラウドドキュメント、ストリームボットモード用であり、グループウェブフック配信は有効にしません。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.MIN_SEVERITY.impact.0": "静的な通知音量に影響を与えます。",
