  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.MIN_SEVERITY.valueNotes.0": "重要度は低い順に info、warning、error、critical です。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.quiet_hours.impact.0": "通知の配信時間に影響します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.quiet_hours.notes.0": "静かな時間帯の静的通知は抑制され、スキップされます。後で配達される予定はありません。",
