  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.quiet_hours.usage": "NOTIFICATION_QUIET_HOURS HH:MM-HH:MMフォーマットを使用し、夜間レンジに対応しています。 NOTIFICATION_TIMEZONE タイムゾーンを指定します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.quiet_hours.valueNotes.0": "沈黙期間を閉じるために空白のスペースを残しましょう。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.quiet_hours.valueNotes.1": "タイムゾーンが空の場合は、ローカルシステムのタイムゾーンが使用されます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.report_output.impact.0": "通知の長さ・言語、および既定言語に依存する Agent Chat の読みやすさに影響します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.report_output.notes.0": "完全な報告は長くなることがあり、プラットフォームによって分割されることがあります。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.report_output.summary": "通知レポートの詳細度、既定の出力言語、テンプレート出力を制御します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.report_output.title": "レポート出力",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.report_output.usage": "REPORT_TYPE は simple/full/brief、REPORT_LANGUAGE は zh/en/ko を指定できます。Agent Chat は context.report_language が省略された場合のみこの既定言語を継承します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.report_output.valueNotes.0": "レポート言語は既定テンプレート、通知文、言語未指定の Agent Chat 応答に影響します。Web UI 言語とは別です。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.SHARE_IMAGE_MAX_CHARS.impact.0": "Web の履歴レポート共有画像生成に影響します。",
