  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.webhooks.valueNotes.0": "ウェブフックのURLには、センシティブなトークンが含まれていることが多いです。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.notification.webhooks.valueNotes.1": "プラットフォームはメッセージの長さ、フォーマット、速度制限に異なっています。",
