  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.MERGE_EMAIL_NOTIFICATION.notes.0": "無効にすると、個別銘柄分析と市場レビューは別々のメールで送信されます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.MERGE_EMAIL_NOTIFICATION.summary": "個別株の分析と市場レビューを一通のメールにまとめて送信してください。",
