  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.REPORT_INTEGRITY_ENABLED.impact.0": "報告書の完全性への影響 LLM 呼び出し回数。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.REPORT_INTEGRITY_ENABLED.notes.0": "REPORT_INTEGRITY_RETRY=0 は再試行を無効にし、プレースホルダーのみを使用します。",
