  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.REPORT_INTEGRITY_ENABLED.valueNotes.0": "不足しているフィールドはプレースホルダーで埋められます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.REPORT_INTEGRITY_ENABLED.valueNotes.1": "再挑戦は増加します LLM 呼び出し回数と呼び出し時間。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.REPORT_RENDERER_ENABLED.impact.0": "最終レポートの出力形式に影響を与えます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.REPORT_RENDERER_ENABLED.notes.0": "有効にする前に、REPORT_TEMPLATES_DIR に有効なテンプレートファイルがあることを確認してください。",
