  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.REPORT_SHOW_LLM_MODEL.notes.0": "モデル切り替えの問題を診断する際に一時的に有効にしてください。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.REPORT_SHOW_LLM_MODEL.summary": "表示してみてください LLM レポートフッター内のモデル名。",
