  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.REPORT_SHOW_LLM_MODEL.valueNotes.0": "レポートレンダリングには影響し、モデル選択、ルーティング、移行には影響しません。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.REPORT_SUMMARY_ONLY.impact.0": "通知内容の詳細レベルに影響します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.REPORT_SUMMARY_ONLY.notes.0": "WebUIでのレポート閲覧には影響しません。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.REPORT_SUMMARY_ONLY.summary": "個別の銘柄詳細は避け、分析要約のみをプッシュしてください。 大量の株式を追跡する際の迅速な概要に理想的です。",
