  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.REPORT_SUMMARY_ONLY.valueNotes.0": "多くの銘柄を追跡する際にこのモードを有効にすると、通知の長さを短縮できます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.REPORT_TEMPLATES_DIR.impact.0": "レポートレンダリングに使われるテンプレートソースに影響を与えます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.REPORT_TEMPLATES_DIR.notes.0": "カスタムテンプレートはJinja2の構文に従い、必要な変数プレースホルダーを含める必要があります。",
