  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.REPORT_TEMPLATES_DIR.title": "レポートテンプレートディレクトリ",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.REPORT_TEMPLATES_DIR.usage": "プロジェクトのルートに対してパスを入力します。ディレクトリにJinja2のテンプレートファイルを配置します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.REPORT_TEMPLATES_DIR.valueNotes.0": "テンプレートを有効にするには REPORT_RENDERER_ENABLED もオンにする必要があります。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.SINGLE_STOCK_NOTIFY.impact.0": "通知のタイミングや頻度に影響します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.SINGLE_STOCK_NOTIFY.notes.0": "多数の銘柄を追跡すると、より多くの通知メッセージを受け取ることがあります。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.report.SINGLE_STOCK_NOTIFY.summary": "各銘柄分析が完了すると、すべてが完了するのを待ってからバッチプッシュするのではなく、すぐにプッシュされます。",
