  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.ADMIN_AUTH_ENABLED.impact.0": "WebUI のログイン、設定へのアクセス、管理者操作に影響します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.ADMIN_AUTH_ENABLED.notes.0": "デプロイ環境で認証データが永続化されることを確認してください。.env を手動で編集した場合は、プロセスを再起動するか、認証設定フローで状態を更新する必要があります。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.ADMIN_AUTH_ENABLED.summary": "WebUI の管理者パスワード保護を有効にします。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.ADMIN_AUTH_ENABLED.title": "ウェブログイン保護",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.ADMIN_AUTH_ENABLED.usage": "WebUI の認証設定から有効または無効にします。必要に応じて python -m src.auth reset_password でパスワードをリセットしてください。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.ADMIN_AUTH_ENABLED.valueNotes.0": "パブリック、共有LAN、またはリバースプロキシ展開に推奨されます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.ADMIN_AUTH_ENABLED.valueNotes.1": "このフィールドは認証設定の流れを回避するため、汎用設定ページで読み取り専用で表示されます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.ANALYSIS_DELAY.impact.0": "全体の分析時間に影響します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.ANALYSIS_DELAY.notes.0": "総消費時間 ≈ 株式数 × 1株あたりの時間 + (株式数 - 1) × ANALYSIS_DELAY。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.ANALYSIS_DELAY.summary": "各株式分析の間隔を秒単位で制御し、速度を制限します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.ANALYSIS_DELAY.title": "解析遅延",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.ANALYSIS_DELAY.usage": "0に設定し、間隔はなし; プラスに設定し、各ストックを完成させた後、次のストックを分析する前に指定された数秒待ちます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.ANALYSIS_DELAY.valueNotes.0": "有用なのは APIs 厳格な料金制限を設けてください。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.daily_brief.impact.0": "スケジュール実行のブリーフ生成と的中率レビューのパネルに影響します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.daily_brief.notes.0": "時刻指定で配信するにはスケジュールモードが必要です。",
