  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.daily_brief.usage": "DAILY_BRIEF_ENABLED で機能を有効にします。DAILY_BRIEF_SCHEDULE_TIME と DAILY_BRIEF_TIMEZONE でスケジュールの時刻を指定します。DAILY_BRIEF_MIN_SAMPLES は的中率を表示するための最小サンプル数を設定します。",
