  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.daily_brief.valueNotes.1": "的中率レビューは参考情報であり、自動売買は行いません。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.DEBUG.impact.0": "ログの詳細や実行時の挙動に影響を与えます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.DEBUG.notes.0": "デバッグモードはパフォーマンスに影響を与えることがあります。長期使用は推奨されません。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.DEBUG.summary": "詳細なログ情報を出力するためにデバッグモードを有効にしてください。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.DEBUG.title": "デバッグモード",
