  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.DEBUG.valueNotes.0": "ログボリュームを減らすために本番環境をシャットダウンすることが推奨されます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.HTTP_PROXY.impact.0": "データソース、LLM、検索、通知のネットワーク通信に影響します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.HTTP_PROXY.notes.0": "コンテナ内では、127.0.0.1はホストマシンではなくコンテナを指しています。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.HTTP_PROXY.summary": "外部 API、モデル、検索リクエスト用の標準的な HTTP プロキシ URL を設定します。",
