  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.HTTP_PROXY.usage": "http://host:port 形式で指定します。HTTPS のプロキシには HTTPS_PROXY を使用できます。完全な URL（認証情報を含む）やライブラリ標準の環境変数が必要な場合は、USE_PROXY よりこちらを優先してください。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.HTTP_PROXY.valueNotes.0": "適用されるかどうかは、基盤となるライブラリや環境の取り扱いに依存します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.HTTP_PROXY.valueNotes.1": "URL に埋め込まれた認証情報は診断で秘匿されます。マスクされていないエクスポートを共有しないでください。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.LOCAL_ONLY_MODE.impact.0": "ローカルバックエンドとキャッシュがパスをカバーしない限り、リモート依存の分析は明確に失敗します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.LOCAL_ONLY_MODE.notes.0": "変更後に再起動してください。docs/local-only-mode_EN.md を参照。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.LOCAL_ONLY_MODE.summary": "ループバック以外のすべての外向き HTTP 宛先をブロックするフェイルクローズプライバシーモード。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.LOCAL_ONLY_MODE.title": "ローカル専用モード",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.LOCAL_ONLY_MODE.usage": "ローカルモデルとキャッシュデータで意図的に実行する場合にのみ有効にしてください。クラウド LLM、検索、ニュース、リモートデータプロバイダー、通知 Webhook は LOCAL_ONLY_MODE エラーコードで拒否されます。純粋なループバックは引き続き許可されます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.LOCAL_ONLY_MODE.valueNotes.0": "デフォルトは false です。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.LOCAL_ONLY_MODE.valueNotes.1": "OUTBOUND_HTTP_ALLOWLIST が有効な間は、loopback を超えて拡張できません。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.LOCAL_ONLY_MODE.valueNotes.2": "ブロックされた呼び出しが黙って通過することはありません。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.LOCAL_RUNTIME_AUTO_DETECT.summary": "セットアップ準備中にローカル Ollama へ高速なループバック検出を行います（ゼロ設定の初回成功）。",
