  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.LOCAL_RUNTIME_DETECT_TIMEOUT_SECONDS.summary": "ローカルランタイム検出プローブのリクエストごとのタイムアウトです。",
