  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.market_review.notes.0": "市場評価は、選ばれた市場におけるインデックスデータソースの利用可能性に依存します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.market_review.summary": "市場レビュー機能(オン/オフ、マーケットサブセット入力、カラースキーム)を制御します。",
