  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.market_review.usage": "MARKET_REVIEW_ENABLED 市場レビューを切り替える;DAILY_MARKET_CONTEXT_ENABLED デフォルトでオンとなり、日々の市場サマリーが株価分析のプロンプトや保守的なガードレールに挿入されるかどうかを制御します。; MARKET_REVIEW_REGION 1つ以上の市場地域を選べますし、 `both` すべての支持市場を維持し、無効または空の選択は `cn`; MARKET_REVIEW_COLOR_SCHEME 色を選ぶ。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.market_review.valueNotes.0": "cn Aシェアをカバーしています。, hk 香港をカバーしています。, us 米国株をカバーしています。, jp 日本をカバーしています。, kr 韓国を扱い、 both すべてをカバーします(cn,hk,us,jp,kr).",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.market_review.valueNotes.1": "MARKET_REVIEW_REGION はマルチセレクトです。例えば、1つ以上の地域を選ぶことができます。 cn, us, jp.",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.market_review.valueNotes.2": "DAILY_MARKET_CONTEXT_ENABLED はデフォルトで有効です。false に設定すると、市場レビューレポートは引き続き生成されますが、その概要は個別銘柄の分析に挿入されず、買い・買い増し推奨を抑制しません。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.market_review.valueNotes.3": "カラースキームはインデックス変更の表示方法に影響を与えます:green_up = 緑は利益、赤は損失;red_up = 赤は利益、緑は損失。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.MAX_WORKERS.impact.0": "インパクト分析に費やした総時間が合計されます API 呼び出し頻度を。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.MAX_WORKERS.notes.0": "労働者が多すぎると原因が増える API レートリミットエラー。",
