  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.PROXY_HOST.impact.0": "USE_PROXY が有効な場合に、プロセスの http_proxy/https_proxy へ適用されるプロキシのエンドポイントを変更します。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.PROXY_HOST.notes.0": "プロキシの認証情報をスクリーンショット、ログ、Issue、共有するプロファイルのエクスポートに貼り付けないでください。",
