  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.PROXY_HOST.summary": "USE_PROXY と組み合わせて次のプロキシ URL を構成するホストです：http://{PROXY_HOST}:{PROXY_PORT}.",
