  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.PROXY_HOST.usage": "ホスト名または IP アドレスを入力します。値には user:pass@host の形式で認証情報を含められるため、設定画面ではこの項目をマスクしています。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.PROXY_HOST.valueNotes.0": "既定値は 127.0.0.1 です。USE_PROXY が有効な場合のみ使用されます。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.PROXY_HOST.valueNotes.1": "USE_PROXY と併せて完全かつ確実に反映するには、プロセスの再起動が必要です。",
  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.PROXY_PORT.impact.0": "USE_PROXY が有効な場合に、プロセスの http_proxy/https_proxy へ適用されるプロキシのエンドポイントを変更します。",
