  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.PROXY_PORT.summary": "USE_PROXY と組み合わせて次のプロキシ URL を構成するポートです：http://{PROXY_HOST}:{PROXY_PORT}.",
