  "locales.settingsHelp.SETTINGS_HELP_MAPS.settings.system.SAVE_CONTEXT_SNAPSHOT.impact.0": "履歴の透明性、コンテキストスナップショットに依存する診断、ウェブレポートのデータソースの要約に影響します。",
